 auto wire=Monstey_Wire(pool,prefix);const auto original=wire;Monstey_FearDbPackedInput input{wire,prefix,initial_calls};const auto field=counter_alias?reinterpret_cast<const std::uint8_t*>(&input.read_calls):reinterpret_cast<const std::uint8_t*>(&input.position);const Monstey_FearDbMemory name_memory{0x70000000,std::span<const std::uint8_t>(field,8)};const auto initial_value=counter_alias?initial_calls:prefix;Monstey_Check((initial_value&255u)!=0,"public success fixture starts with nonempty filename");Monstey_FearDbResources resources;
