 if(references==3){Monstey_Check(existing==db&&again==db&&comparisons==2&&Monstey_Get(resources.allocations[0],db+16)==3,"alias filename cache hits retain real resource");}else{Monstey_Check(existing==0&&again==0&&comparisons==0&&Monstey_Get(resources.allocations[0],db+16)==1,"filename that became empty after load retains native later-query guards");}
 Monstey_Check(ignored.position==999&&ignored.read_calls==77&&input.position==current_position&&input.read_calls==current_calls,"cache/empty-name branch does not consume any loader input or bad allocation identity");for(unsigned i=0;i<references;++i){const auto release=Monstey_FearDbReleaseDatabase(resources,db);Monstey_Check(release.kind==(i+1==references?Monstey_FearDbReleaseKind::freed:Monstey_FearDbReleaseKind::retained),"public alias lifetime releases exactly its actual references");}Monstey_Check(resources.allocations.empty()&&resources.cache.empty()&&wire==original&&input.position==prefix+32u+pool&&input.read_calls==initial_calls+3,"public alias chain ends cleanly, preserving caller source and progress");
 if(prefix==1&&pool==227&&!counter_alias)Monstey_Check(used==250&&0x30000000u+used==0x300000fau,"exact reachable public prefix1/pool227 layout");++Monstey_Cases;
