void Monstey_ReadCalls(){for(auto initial:std::array<std::uint64_t,3>{254,255,65534})for(auto pool:std::array<Monstey_U32,2>{0,228})Monstey_Run(pool,0,initial,true);++Monstey_Groups;}
void Monstey_ZeroGuard(){auto wire=Monstey_Wire(228);Monstey_FearDbPackedInput input{wire};const auto field=reinterpret_cast<const std::uint8_t*>(&input.position);const Monstey_FearDbMemory memory{0x70000000,std::span<const std::uint8_t>(field,8)};Monstey_FearDbResources resources;const auto none=Monstey_FearDbOpenNew(resources,memory,0x70000000,input,0x30000000,{});Monstey_Check(none==0&&input.position==0&&input.read_calls==0&&resources.allocations.empty()&&resources.cache.empty(),"zero initial cursor is correctly rejected by public first-byte guard");const auto direct=Monstey_FearDbLoadPacked(input,memory.bytes,0x30000000);Monstey_Check(direct.image.has_value()&&direct.image->used_bytes==251,"direct loader alias remains supported without pretending public guard is absent");++Monstey_Cases;++Monstey_Groups;}
