 {auto wire=Monstey_Wire(0,0,0);Monstey_FearDbPackedInput input{wire,0,254};const auto field=reinterpret_cast<const std::uint8_t*>(&input.read_calls);Monstey_FearDbResources resources;bool caught=false;try{(void)Monstey_FearDbOpenNew(resources,{0x70000000,std::span<const std::uint8_t>(field,8)},0x70000000,input,0x30000000,{});}catch(const Monstey_FearDbFault&e){caught=e.address==0x30000016&&e.width==1&&e.writing;}Monstey_Check(caught&&input.position==32&&input.read_calls==257&&resources.allocations.empty()&&resources.cache.empty(),"consumed copy write failure is not hidden by public open or repaired allocation");++Monstey_Cases;}
